def segments_of(a, mode):
    H,W=len(a),len(a[0])
    if mode=='diag':
        D={}
        for i in range(H):
            for j in range(W):
                if a[i][j]:
                    d=j-i
                    if d not in D: D[d]=[]
                    D[d].append(a[i][j])
        return D
    else:
        R={}
        for i in range(H):
            row=a[i]
            nz=all(x==row[0] for x in row) if any(row) else False
            if any(x for x in row):
                v=row[0]
                R[i]=v
        return R

def solve(inp, mode='diag'):
    H,W=len(inp),len(inp[0])
    if mode=='diag':
        if not all(len(set(r))==1 or True for r in inp): mode='diag'; S=segments_of(inp,'diag')
        else: S=R=segments_of(inp,'row'); mode='row'
    else: S=segments_of(inp,'row'); mode='row'
    if mode=='diag':
        S=segments_of(inp,'diag'); 
    elif mode=='row':
        S=segments_of(inp,'row')
    # try both modes if ambiguous
    for md,m in (('diag',S),('row',S)):
        for p in range(1,200):
            M={}
            ok=True
            for d,c in m.items():
                r=d%p
                if r in M:
                    if M[r]!=c: ok=False;break
                    # else majority - simplified: ignore equal colors
                M[r]=c
            if not ok: continue
            undefined=[r for r in range(p) if r not in M]
            if not undefined:
                final={k:v for k,v in M.items()}
                break
            out=None
            def fill(i,d0):
                nonlocal out
                if d0<p and d0 in M: out=M[d0];return
                for r in range(d0-1,-1,-1):
                    if r in M: out=M[r];return
                    d0=r
                    if d0<0: return
                return
            final={r:fill(r,None) for r in range(p)}
            if any(final[r] is None for r in range(p)): continue
            break
        else: continue
        out=[[final[(j-i)%p] for j in range(W)] for i in range(H)]
        break
    return out

