def raytrace(inp):
    H,W=len(inp),len(inp[0])
    segs=[]
    seen=set()
    for i in range(H):
        for j in range(W):
            if inp[i][j] and (i-1,j-1) not in seen:
                k=0; c=inp[i][j]
                while 0<=i+k<H and 0<=j+k<W and inp[i+k][j+k]==c: k+=1
                for m in range(k): seen.add((i+m,j+m))
                segs.append({'color':c,'cells':list(zip(range(i,i+k),range(j,j+k)))})
    return segs

def firsthit(inp):
    H,W=len(inp),len(inp[0])
    hits={}
    for s in raytrace(inp):
        t=0; x,y=s['cells'][0]
        while True:
            key=(x%W, y%H)
            if key in hits and hits[key]<t: break
            hits[(x,y)]=t
            x+=1; y+=1
            x%=W; y%=H
    res=[[None]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            t,hits.get((i,j))
            res[i][j]=hits.get((i,j))
    return res

